#include "dm/core.hpp"
#include <algorithm>
#include <cctype>
#include <sstream>
#include <stdexcept>
namespace dm{
std::string lower(std::string s){for(auto& c:s)c=char(std::tolower((unsigned char)c));return s;}
std::string trim(std::string s){auto a=s.find_first_not_of(" \t\r\n"),b=s.find_last_not_of(" \t\r\n");return a==std::string::npos?"":s.substr(a,b-a+1);}
uint64_t number(const std::string& s){if(s.empty()||s.find_first_not_of("0123456789")!=std::string::npos)throw std::runtime_error("Invalid unsigned integer");return std::stoull(s);}
Url Url::parse(const std::string& s){if(s.size()>16384||s.empty())throw std::runtime_error("Invalid URL length");for(unsigned char c:s)if(c<=32||c==127||c=='\\')throw std::runtime_error("Invalid URL character");auto p=s.find("://");if(p==std::string::npos)throw std::runtime_error("HTTP(S) URL required");Url u;u.scheme=lower(s.substr(0,p));if(u.scheme!="http"&&u.scheme!="https")throw std::runtime_error("Unsupported URL scheme");auto end=s.find_first_of("/?#",p+3);u.authority=s.substr(p+3,end==std::string::npos?end:end-p-3);if(u.authority.empty()||u.authority.find('@')!=std::string::npos)throw std::runtime_error("Invalid authority or embedded credentials");u.authority=lower(u.authority);u.path=end==std::string::npos?"/":s.substr(end);u.path=u.path.substr(0,u.path.find('#'));if(u.path.empty()||u.path[0]!='/')u.path="/"+u.path;return u;}
std::string Url::str()const{return scheme+"://"+authority+path;}
std::string encode(const std::string& s){const char* hex="0123456789ABCDEF";std::string o;for(unsigned char c:s){if(std::isalnum(c)||c=='-'||c=='_'||c=='.'||c=='~')o+=c;else{o+='%';o+=hex[c>>4];o+=hex[c&15];}}return o;}
std::string safeName(std::string s){for(auto& c:s)if((unsigned char)c<32||std::string("/\\:*?\"<>|").find(c)!=std::string::npos)c='_';while(!s.empty()&&(s.back()=='.'||s.back()==' '))s.pop_back();while(!s.empty()&&(s[0]=='.'||s[0]==' '))s.erase(0,1);if(s.size()>150)s.resize(150);auto b=lower(s.substr(0,s.find('.')));if(b=="con"||b=="prn"||b=="aux"||b=="nul"||b.rfind("com",0)==0||b.rfind("lpt",0)==0)s="_"+s;return s.empty()?"download.bin":s;}
std::string redirect(const std::string& base,const std::string& loc){auto u=Url::parse(base);std::string s;if(loc.find("://")!=std::string::npos)s=loc;else if(loc.rfind("//",0)==0)s=u.scheme+":"+loc;else if(!loc.empty()&&loc[0]=='/')s=u.scheme+"://"+u.authority+loc;else if(!loc.empty()&&loc[0]=='?')s=u.scheme+"://"+u.authority+u.path.substr(0,u.path.find('?'))+loc;else{s=u.scheme+"://"+u.authority;auto path=u.path.substr(0,u.path.find('?'));s+=path.substr(0,path.find_last_of('/')+1)+loc;}auto result=Url::parse(s);if(u.scheme=="https"&&result.scheme!="https")throw std::runtime_error("HTTPS downgrade rejected");return result.str();}
void fetch(Transport& t,Request r,Head head,Body body,std::atomic<bool>& stop){r.url=Url::parse(r.url).str();for(int n=0;n<10;n++){Response h;bool red=false;t.perform(r,[&](const Response& x){h=x;red=x.status==301||x.status==302||x.status==303||x.status==307||x.status==308;if(!red)head(x);},[&](const char* p,size_t size){if(!red)body(p,size);},stop);if(!red)return;if(r.method!="GET"&&r.method!="HEAD")throw std::runtime_error("API redirect rejected");if(!h.headers.count("location"))throw std::runtime_error("Missing redirect Location");auto next=redirect(r.url,h.headers.at("location"));if(Url::parse(next).authority!=Url::parse(r.url).authority){for(auto i=r.headers.begin();i!=r.headers.end();)if(lower(i->first)=="authorization"||lower(i->first)=="cookie")i=r.headers.erase(i);else ++i;}r.url=next;}throw std::runtime_error("Too many redirects");}
Json requestJson(Transport& t,Request r,std::atomic<bool>& stop){std::string b;Response h;fetch(t,r,[&](const Response& x){h=x;},[&](const char* p,size_t n){if(b.size()+n>4*1024*1024)throw std::runtime_error("API response too large");b.append(p,n);},stop);if(h.status<200||h.status>=300)throw std::runtime_error("API HTTP "+std::to_string(h.status));return b.empty()?Json::object():Json::parse(b);}
Resolved DirectResolver::resolve(const std::string& u){Request r;r.url=Url::parse(u).str();r.method="HEAD";Resolved o{r.url,"",0};std::atomic<bool> stop{false};fetch(net,r,[&](const Response& h){if(h.status<200||h.status>=300)throw std::runtime_error("HEAD failed: "+std::to_string(h.status));if(h.headers.count("content-type")&&lower(h.headers.at("content-type")).find("text/html")!=std::string::npos)throw std::runtime_error("HTML page needs a provider resolver");if(h.headers.count("content-length"))o.size=number(h.headers.at("content-length"));if(h.headers.count("content-disposition")){auto d=h.headers.at("content-disposition");auto p=d.find("filename=\"");if(p!=std::string::npos)o.name=safeName(d.substr(p+10,d.find('"',p+10)-p-10));}},[](const char*,size_t){},stop);if(o.name.empty()){auto p=Url::parse(u).path;p=p.substr(0,p.find('?'));o.name=safeName(p.substr(p.find_last_of('/')+1));}return o;}
}
